def day(i, d):
    t, th, st, task, n, crit, err, qs = d
    q = "".join(f"<li>{x}</li>" for x in qs)
    return f'''<article class="day"><div class="dn">День {i}</div><h4>{t}</h4><dl>
<dt>📖 Теорія</dt><dd>{th}</dd><dt>⚙️ Налаштування</dt><dd>{st}</dd><dt>🎯 Завдання</dt><dd>{task}</dd><dt>🔢 Кадрів</dt><dd>≈ {n}</dd>
<dt>✅ Критерії</dt><dd>{crit}</dd><dt>❌ Типові помилки</dt><dd>{err}</dd><dt>❓ Самоперевірка</dt><dd><ol>{q}</ol></dd></dl>
<label class="done"><input type="checkbox" data-done="day{i}"> Виконано</label></article>'''


